function validate([positions, healths, directions]) {
  if (!Array.isArray(positions) || positions.length < 1 || positions.length > 100000) return 'positions needs 1 to 10^5 robots.';
  if (!Array.isArray(healths) || healths.length !== positions.length) return 'healths needs one value per robot.';
  if (typeof directions !== 'string' || directions.length !== positions.length) return 'directions needs one letter per robot.';
  if (!/^[LR]*$/.test(directions)) return "directions may contain only 'L' and 'R'.";
  if (positions.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each position is an integer from 1 to 10^9.';
  if (healths.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each health is an integer from 1 to 10^9.';
  if (new Set(positions).size !== positions.length) return 'All positions must be different.';
  return null;
}

