  const n = positions.length;
  const health = healths.slice();
  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((a, b) => positions[a] - positions[b]);
  const stack = [];

  for (const i of order) {
    if (directions[i] === 'R') {
      stack.push(i);
      continue;
    }
    while (stack.length > 0 && health[i] > 0) {
      const top = stack[stack.length - 1];
      if (health[top] < health[i]) {
        health[top] = 0;
        stack.pop();
        health[i] -= 1;
      } else if (health[top] > health[i]) {
        health[top] -= 1;
        health[i] = 0;
      } else {
        health[top] = 0;
        stack.pop();
        health[i] = 0;
      }
    }
  }
  return health.filter(h => h > 0);
}

