function survivedRobotsHealths(positions, healths, directions) {
  // Resolve collisions one by one in time order: a right-mover at p whose next robot is a
  // left-mover at q meets it after (q - p) / 2 time units, so the smallest gap goes first.
  const n = positions.length;
  const health = healths.slice();
  let alive = Array.from({ length: n }, (_, i) => i).sort((a, b) => positions[a] - positions[b]);
  for (;;) {
    let first = -1;
    let gap = Infinity;
    for (let k = 0; k + 1 < alive.length; k++) {
      const a = alive[k], b = alive[k + 1];
      if (directions[a] === 'R' && directions[b] === 'L' && positions[b] - positions[a] < gap) {
        gap = positions[b] - positions[a];
        first = k;
      }
    }
    if (first === -1) break;
    const a = alive[first], b = alive[first + 1];
    if (health[a] === health[b]) { health[a] = 0; health[b] = 0; }
    else if (health[a] > health[b]) { health[b] = 0; health[a]--; }
    else { health[a] = 0; health[b]--; }
    alive = alive.filter(i => health[i] > 0);
  }
  const result = [];
  for (let i = 0; i < n; i++) if (health[i] > 0) result.push(health[i]);
  return result;
}

