function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 7);
  const span = size === 'large' ? 1000000000 : 20;
  const top = size === 'large' ? (rand() < 0.5 ? 1000000000 : 40) : (rand() < 0.8 ? 5 : 1000000000);
  const seen = new Set();
  const positions = [];
  while (positions.length < n) {
    const value = 1 + Math.floor(rand() * span);
    if (!seen.has(value)) { seen.add(value); positions.push(value); }
  }
  const healths = positions.map(() => 1 + Math.floor(rand() * top));
  const rightShare = 0.2 + 0.6 * rand();
  const directions = positions.map(() => (rand() < rightShare ? 'R' : 'L')).join('');
  return [positions, healths, directions];
}
